  "inlineSchema": "// ContentEngine data model.\n//\n// Auth models (User/Account/Session/VerificationToken) match the shape the\n// @next-auth/prisma-adapter expects. Billing (Subscription) and quota\n// (UsageRecord) are ContentEngine-specific and are driven by the plan config\n// in @org/shared.\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n  runtime  = \"nodejs\"\n}\n\nmodel User {\n  id                String             @id @default(cuid())\n  name              String?\n  email             String?            @unique\n  emailVerified     DateTime?\n  image             String?\n  accounts          Account[]\n  sessions          Session[]\n  subscription      Subscription?\n  usageRecords      UsageRecord[]\n  socialConnections SocialConnection[]\n  socialPosts       SocialPost[]\n  repurposeJobs     RepurposeJob[]\n  settings          UserSettings?\n  createdAt         DateTime           @default(now())\n  updatedAt         DateTime           @updatedAt\n}\n\n/// A user's content-generation preferences, captured at onboarding and editable\n/// later. `tone` holds a ContentTone id and `formats` holds GenerationFormat ids\n/// (keys of RepurposedContent) from @org/shared; both are strings so the\n/// catalogues can evolve without a migration. `onboardedAt` is null until the\n/// user completes first-run setup — the web app redirects to onboarding while it\n/// is null. One row per user, created lazily on first save.\nmodel UserSettings {\n  id          String    @id @default(cuid())\n  userId      String    @unique\n  tone        String    @default(\"professional\")\n  customTone  String?\n  formats     String[]\n  audience    String?\n  guidance    String?   @db.Text\n  emojis      Boolean   @default(true)\n  hashtags    Boolean   @default(true)\n  language    String    @default(\"English\")\n  onboardedAt DateTime?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel Account {\n  id                String  @id @default(cuid())\n  userId            String\n  type              String\n  provider          String\n  providerAccountId String\n  refresh_token     String? @db.Text\n  access_token      String? @db.Text\n  expires_at        Int?\n  token_type        String?\n  scope             String?\n  id_token          String? @db.Text\n  session_state     String?\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([provider, providerAccountId])\n}\n\nmodel Session {\n  id           String   @id @default(cuid())\n  sessionToken String   @unique\n  userId       String\n  expires      DateTime\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel VerificationToken {\n  identifier String\n  token      String   @unique\n  expires    DateTime\n\n  @@unique([identifier, token])\n}\n\nenum SubscriptionStatus {\n  active\n  trialing\n  past_due\n  canceled\n  incomplete\n  incomplete_expired\n  unpaid\n}\n\n/// One row per user. `plan` holds a PlanId (\"free\" | \"pro\" | \"team\") from\n/// @org/shared; it is kept as a string so the plan catalogue can evolve\n/// without a schema migration.\nmodel Subscription {\n  id                   String             @id @default(cuid())\n  userId               String             @unique\n  plan                 String             @default(\"free\")\n  status               SubscriptionStatus @default(active)\n  stripeCustomerId     String?            @unique\n  stripeSubscriptionId String?            @unique\n  stripePriceId        String?\n  currentPeriodEnd     DateTime?\n  cancelAtPeriodEnd    Boolean            @default(false)\n  createdAt            DateTime           @default(now())\n  updatedAt            DateTime           @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\n/// Monthly generation counter, one row per user per period (\"YYYY-MM\").\n/// The unique constraint lets the API upsert-and-increment atomically.\nmodel UsageRecord {\n  id        String   @id @default(cuid())\n  userId    String\n  period    String\n  count     Int      @default(0)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, period])\n}\n\n/// One saved repurpose generation, so users can revisit past results. `source`\n/// is the raw input (URL or pasted text); `content` is the full\n/// RepurposedContent payload from @org/shared, stored as JSON so the shape can\n/// evolve without a migration.\nmodel RepurposeJob {\n  id         String   @id @default(cuid())\n  userId     String\n  source     String   @db.Text\n  sourceType String\n  content    Json\n  createdAt  DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId, createdAt])\n}\n\n/// A user's linked social account for one platform. `platform` holds a\n/// SocialPlatform value (\"linkedin\" | \"x\" | \"facebook\" | \"instagram\" |\n/// \"tiktok\") from @org/shared; kept as a string so the catalogue can grow\n/// without a migration. OAuth tokens are stored encrypted (AES-256-GCM) — the\n/// database never holds a plaintext access/refresh token.\nmodel SocialConnection {\n  id                String    @id @default(cuid())\n  userId            String\n  platform          String\n  externalAccountId String\n  displayName       String?\n  accessToken       String    @db.Text\n  refreshToken      String?   @db.Text\n  scope             String?\n  expiresAt         DateTime?\n  /// Platform-specific extras (e.g. a Facebook Page token, an Instagram\n  /// business account id) stored as encrypted JSON string values by the caller.\n  metadata          Json?\n  createdAt         DateTime  @default(now())\n  updatedAt         DateTime  @updatedAt\n\n  user  User         @relation(fields: [userId], references: [id], onDelete: Cascade)\n  posts SocialPost[]\n\n  @@unique([userId, platform, externalAccountId])\n  @@index([userId])\n}\n\nenum PublishStatus {\n  draft\n  scheduled\n  publishing\n  published\n  failed\n}\n\n/// A single piece of content queued for or delivered to a social platform.\n/// `scheduledFor` in the future means the poller publishes it later; null means\n/// publish immediately. `externalPostId` is the id returned by the platform on\n/// success; `error` captures the failure reason otherwise.\nmodel SocialPost {\n  id             String        @id @default(cuid())\n  userId         String\n  connectionId   String\n  platform       String\n  content        String        @db.Text\n  mediaUrls      String[]\n  status         PublishStatus @default(draft)\n  scheduledFor   DateTime?\n  publishedAt    DateTime?\n  externalPostId String?\n  error          String?\n  createdAt      DateTime      @default(now())\n  updatedAt      DateTime      @updatedAt\n\n  user       User             @relation(fields: [userId], references: [id], onDelete: Cascade)\n  connection SocialConnection @relation(fields: [connectionId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([status, scheduledFor])\n}\n",
